```cpp
#include <algorithm>
#include <cstdlib>
#include <fstream>
#include <iostream>
#include <vector>
using namespace std;
struct Point { long long x, y; };
long long distance_between(const Point& a, const Point& b) {
    return llabs(a.x - b.x) + llabs(a.y - b.y);
}
void solve(istream& in, ostream& out) {
    int n; in >> n;
    vector<Point> p(n);
    for (int i = 0; i < n; ++i) in >> p[i].x >> p[i].y;
    long long total = 0, saving = 0;
    for (int i = 1; i < n; ++i) total += distance_between(p[i-1], p[i]);
    for (int i = 1; i + 1 < n; ++i) {
        long long candidate = distance_between(p[i-1], p[i])
                            + distance_between(p[i], p[i+1])
                            - distance_between(p[i-1], p[i+1]);
        saving = max(saving, candidate);
    }
    out << total - saving << '\n';
}
int main() {
    ifstream in("marathon.in");
    ofstream out("marathon.out");
    solve(in, out);
    return 0;
}
