#include <fstream>
#include <iostream>
#include <string>
#include <utility>
#include <vector>
using namespace std;
void solve(istream& in, ostream& out) {
    int n, m; in >> n >> m;
    vector<string> grid(n);
    for (int r = 0; r < n; ++r) in >> grid[r];
    vector<pair<int, int> > clues;
    for (int r = 0; r < n; ++r) {
        for (int c = 0; c < m; ++c) {
            if (grid[r][c] != '.') continue;
            bool horizontal = (c == 0 || grid[r][c-1] == '#')
                           && c + 2 < m && grid[r][c+1] == '.' && grid[r][c+2] == '.';
            bool vertical = (r == 0 || grid[r-1][c] == '#')
                         && r + 2 < n && grid[r+1][c] == '.' && grid[r+2][c] == '.';
            if (horizontal || vertical) clues.push_back(make_pair(r+1, c+1));
        }
    }
    out << clues.size() << '\n';
    for (size_t i = 0; i < clues.size(); ++i) out << clues[i].first << ' ' << clues[i].second << '\n';
}
int main() {
    ifstream in("crosswords.in");
    ofstream out("crosswords.out");
    solve(in, out);
    return 0;
}
