#include <fstream>
#include <iostream>
#include <vector>
using namespace std;
void solve(istream& in, ostream& out) {
    int n; in >> n;
    vector<long long> speed(n);
    for (int i = 0; i < n; ++i) {
        long long position; in >> position >> speed[i];
    }
    long long slowest_ahead = 1000000001LL;
    int groups = 0;
    for (int i = n - 1; i >= 0; --i) {
        if (speed[i] <= slowest_ahead) {
            ++groups;
            slowest_ahead = speed[i];
        }
    }
    out << groups << '\n';
}
int main() {
    ifstream in("cowjog.in");
    ofstream out("cowjog.out");
    solve(in, out);
    return 0;
}
