#include <algorithm>
#include <fstream>
#include <iostream>
#include <string>
#include <utility>
#include <vector>
using namespace std;
long long count_in_range(long long left, long long right, long long a, long long b) {
    left = max(left, a);
    right = min(right, b);
    return left <= right ? right - left + 1 : 0;
}
void solve(istream& in, ostream& out) {
    int n; long long a, b; in >> n >> a >> b;
    vector<pair<long long, bool> > cows;
    for (int i = 0; i < n; ++i) {
        string label; long long weight; in >> label >> weight;
        cows.push_back(make_pair(weight, label == "S"));
    }
    sort(cows.begin(), cows.end());
    long long answer = 0;
    if (cows.front().second) answer += count_in_range(1, cows.front().first - 1, a, b);
    if (cows.back().second) answer += count_in_range(cows.back().first + 1, 1000000000LL, a, b);
    for (int i = 0; i < n; ++i) {
        if (cows[i].second) answer += count_in_range(cows[i].first, cows[i].first, a, b);
        if (i + 1 == n) continue;
        long long u = cows[i].first, v = cows[i+1].first, sum = u + v;
        if (cows[i].second) answer += count_in_range(u + 1, (sum - 1) / 2, a, b);
        if (cows[i+1].second) answer += count_in_range(sum / 2 + 1, v - 1, a, b);
        if (sum % 2 == 0 && (cows[i].second || cows[i+1].second)) {
            answer += count_in_range(sum / 2, sum / 2, a, b);
        }
    }
    out << answer << '\n';
}
int main() {
    ifstream in("learning.in");
    ofstream out("learning.out");
    solve(in, out);
    return 0;
}
